input.command:
cd /Users/myankelev/Code/random/cipher-box
REPO_OWNER=FSM1; REPO_NAME=cipher-box; PR=811
echo "=== reviewThreads (unresolved) ==="
env -u GITHUB_TOKEN gh api graphql -f query="
{
  repository(owner: \"$REPO_OWNER\", name: \"$REPO_NAME\") {
    pullRequest(number: $PR) {
      isDraft
      reviewDecision
      reviewThreads(first: 100) {
        nodes { id isResolved comments(first:1){ nodes { author{login} path line } } }
      }
    }
  }
}" --jq '{isDraft: .data.repository.pullRequest.isDraft, threads: [.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | {author: .comments.nodes[0].author.login, path: .comments.nodes[0].path, line: .comments.nodes[0].line}]}'
echo "=== reviews (summary bodies) ==="
env -u GITHUB_TOKEN gh api repos/$REPO_OWNER/$REPO_NAME/pulls/$PR/reviews --jq '[.[] | {author: .user.login, state: .state, snippet: (.body[0:80])}]'
echo "=== issue comments (bot walkthroughs) ==="
env -u GITHUB_TOKEN gh api repos/$REPO_OWNER/$REPO_NAME/issues/$PR/comments --jq '[.[] | {author: .user.login, snippet: (.body[0:80])}]'
